function findMissingNumbers(arr) {
  if (arr.length === 0) return [];

  const missing = [];
  const min = arr[0];
  const max = arr[arr.length - 1];

  for (let i = min; i <= max; i++) {
    if (!arr.includes(i)) {
      missing.push(i);
    }
  }

  return missing;
}

console.log(findMissingNumbers([1, 2, 3, 4, 7, 9, 11, 13, 15]));
